package com.onebytelabs.zlplay.audio;
/** Native REAPER click fallback; generated by sample position, never by wall clock. */
public final class ProjectClickTrack extends PcmTrack {
 private final double seconds,beat;private final int meter;
 public ProjectClickTrack(double seconds,double bpm,int meter){super("Click",DemoMixer.RATE,2);this.seconds=seconds;this.beat=DemoMixer.RATE*60/bpm;this.meter=meter;}
 @Override public double duration(){return seconds;}
 @Override public float sample(long frame,int channel){if(frame<0||frame>=seconds*DemoMixer.RATE)return 0;return NativeClickSound.sample(frame,beat,meter,channel);}
 @Override public float previewPeak(double second){return second>=0&&second<seconds?.13f:0;}
 @Override public void addPeaks(float[] into,double duration){}
 @Override public long decodedBytes(){return 0;}
}
